/* Velocity-driven elastic response. Exact damped spring: stable at 30/60/120 Hz. */
export function createPhotoInertia(){return {previous:null,time:null,bend:0,velocity:0,speed:0};}
export function resetPhotoInertia(s){s.previous=s.time=null;s.bend=s.velocity=s.speed=0;}
export function stepPhotoInertia(s,progress,time,reduced=false){
 const dt=s.time===null?0:Math.max(0,time-s.time);
 if(reduced||s.previous===null||dt>.2){s.bend=s.velocity=s.speed=0;}
 else if(dt>0){
  s.speed=(progress-s.previous)/dt;
  const target=Math.tanh(s.speed*.24),omega=14,damping=.66;
  const a=omega*damping,b=omega*Math.sqrt(1-damping*damping),e=Math.exp(-a*dt);
  const x=s.bend-target,c=Math.cos(b*dt),sn=Math.sin(b*dt),k=(s.velocity+a*x)/b;
  s.bend=target+e*(x*c+k*sn);
  s.velocity=e*(s.velocity*c-(a*s.velocity+omega*omega*x)/b*sn);
 }
 s.previous=progress;s.time=time;
 return s.bend;
}
